import React from "react";
import {argTypes as linePlotArgTypes} from "./LinePlot.args.jsx";
import {assign} from "@d3plus/dom";

import {FanChart as D3plusFanChart} from "@d3plus/react";
export const FanChart = ({ config }) => <D3plusFanChart config={config} />;

export const argTypes = assign(

  /**
   * Filters out unused argTypes from the LinePlot primitive and
   * overrides any defaults that have been changed in FanChart
   */
  Object.keys(linePlotArgTypes)
    .filter(k => !k.match(/^(barPadding|groupPadding|swarm|swarmConfig)$/))
    .reduce((obj, k) => (obj[k] = linePlotArgTypes[k], obj), {}),

  /**
   * FanChart-specific methods
   */
  
  {
    forecast: {
      defaultValue: "auto",
      description: "Marks a forecast: the stretch of the discrete axis after it gets a\nshaded backdrop, a rule at its start, and a translated \"Forecast\"\nlabel, and each line's forecast stretch is dashed (see\n`forecastConfig`). A function flags the forecast rows (e.g.\n`d => d.Type === \"Predicted\"`): each line is dashed from its last\nunflagged point, or throughout when every row is flagged, and the\nbackdrop starts at the earliest of those. `\"auto\"` (or `true`) flags\nthe rows whose `confidence` bounds spread away from their line. A\ndiscrete-axis value (a date or year on a time axis) starts the\nforecast there. Unset (the default), only a trend line projection\n(`trendLineConfig.projection`) is marked, from the last fitted value;\n`false` marks nothing, not even a projection. On bar charts the\nbackdrop starts at the edge of the first forecast bar, and bars keep\ntheir own styles. Defaults to `\"auto\"` on a FanChart.\n\nOn by default, so each line's forecast starts where its `confidence` bands open.",
      table: {
        defaultValue: {
          summary: "auto"
        }
      }
    }
  }
);
